import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷四·4","description":"易小帖 - 卷四·4","frontmatter":{"title":"卷四·4","description":"易小帖 - 卷四·4"},"headers":[],"relativePath":"zh/classics/yixiaotie/098.md","filePath":"zh/classics/yixiaotie/098.md"}'),o={name:"zh/classics/yixiaotie/098.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷四·4",tabindex:"-1"},[r("卷四·4 "),e("a",{class:"header-anchor",href:"#卷四·4","aria-label":"Permalink to “卷四·4”"},"​")],-1),e("p",null,"觀卦「觀我生」生字最難解。京房謂：大臣當觀賢人之性以貢於王。直以性字釋生字，猶是近理。若朱楓林竟以「生之謂性」之生字當之，則以文王演易而襲戰國告子之言以為辭，真笑話矣。至虞氏易謂：生即是民，如憑生蒼生之生。雖觀我觀民於易義未合，然猶顧字義。而王弼以生為道，程氏以道德行義皆為生，朱氏則專取行字而曰我生者我之所行，則不惟易義無涉，試問：從來有此字義否乎？",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
